const tasks = $('4. Fetch Pending Tasks').all().map(i => i.json);
const members = $('5. Fetch Members Metrics').all().map(i => i.json);
const project =$('3. Fetch Active Project').first().json;

let totalStoryPoints = 0;
let urgentCount = 0;

for (const t of tasks) {
  const points = Number(t.story_points);
  totalStoryPoints += isNaN(points) ? 1 : points;
  if (t.priority === 'URGENT' || t.priority === 'HIGH') {
    urgentCount += 1;
  }
}

return [{
  json: {
    project: project,
    tasks: tasks,
    members: members,
    metrics: {
      total_tasks: tasks.length,
      total_story_points: totalStoryPoints,
      urgent_tasks_count: urgentCount
    }
  }
}];

const data = $input.item.json;
const currentTime = new Date().toISOString();

const prompt = `
Bạn là Trợ lý AI Chuyên gia Quản lý Dự án & Đánh giá Rủi ro (Risk Analysis Agent).
Thời gian hiện tại: ${currentTime}

THÔNG TIN DỰ ÁN:
Tên dự án: ${data.project.name}
Hạn chót dự án: ${data.project.deadline}

THỐNG KÊ KHỐI LƯỢNG CÔNG VIỆC:
- Tổng số task chưa hoàn thành: ${data.metrics.total_tasks}
- Tổng điểm Story Points: ${data.metrics.total_story_points}
- Số lượng task ưu tiên cao/khẩn cấp: ${data.metrics.urgent_tasks_count}

CHI TIẾT DANH SÁCH TASK:
${JSON.stringify(data.tasks, null, 2)}

NĂNG LỰC THÀNH VIÊN:
${JSON.stringify(data.members, null, 2)}

Hãy phân tích kỹ năng, tiến độ, thời hạn deadline và khối lượng công việc để đưa ra đánh giá rủi ro trễ hạn.

BẮT BUỘC TRẢ VỀ ĐỊNH DẠNG JSON THUẦN TÚY (không dùng markdown codeblock), với cấu trúc chính xác sau:
{
  "risk_score": <số thực từ 0 đến 100 biểu thị mức độ rủi ro trễ hạn>,
  "ai_summary": "<đánh giá chi tiết, chỉ ra các điểm nghẽn và nguyên nhân rủi ro>"
}
`;

return [{ json: { ai_prompt: prompt, project_id: data.project.id, metrics_json: data.metrics } }];

const itemJson = $input.item.json;
let rawText = '';

if (itemJson.response) {
  rawText = itemJson.response;
} else if (itemJson.text) {
  rawText = itemJson.text;
}

let parsed = { risk_score: 50, ai_summary: 'Không thể trích xuất phản hồi từ AI.' };

try {
  const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed.ai_summary = rawText;
}

const promptNode = $('7. Build AI Prompt Structure').first().json;

return [{
  json: {
    project_id: promptNode.project_id,
    report_type: 'DEADLINE_RISK',
    risk_score: parsed.risk_score,
    ai_summary: parsed.ai_summary,
    metrics: promptNode.metrics_json
  }
}];

const item = $input.item.json;
if (item.risk_score < 0) item.risk_score = 0;
if (item.risk_score > 100) item.risk_score = 100;
return [{ json: item }];
